SELECT analytics_order_facts.customer_segment, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 9 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' GROUP BY analytics_order_facts.customer_segment ORDER BY order_count DESC, analytics_order_facts.customer_segment ASC LIMIT 6
